 async function submit(e,status='ready'){e?.preventDefault();if(guard.current)return;guard.current=true;setBusy('save');setError('');try{await persist(status);notify(status==='ready'?'Kosakata disimpan. Kartu latihan sudah siap.':'Draf disimpan. Bisa dilanjutkan kapan saja.');onClose()}catch(e){setError(e.name==='ZodError'?'Lengkapi kata, arti, penjelasan, dan kedua contoh sebelum menyimpan.':e.message)}finally{guard.current=false;setBusy('')}}
 async function generate(){if(guard.current)return;if(!form.word.trim()){setError('Masukkan kata atau frasa pendek dahulu.');return;}if(generated&&!await confirmAction('AI akan mengganti penjelasan, contoh, dan pelafalan yang sedang kamu edit. Lanjutkan?'))return;
  guard.current=true;setBusy('ai');setError('');try{await persist(entry?.status==='ready'?'ready':'draft');setSavedDraft(true);const input={word:form.word.trim(),source:form.source,context:form.context};const signature=JSON.stringify(input);if(!request.current||request.current.signature!==signature)request.current={id:uid(),signature};const r=await(await w.api('/api/generate',{method:'POST',body:JSON.stringify({id:request.current.id,...input})})).json();if(mounted.current){setForm(f=>({...f,...combineMeanings(r,input.source,input.word)}));setImageSuggestion({id:uid(),query:r.imageQuery||r.meanings[0].en});setGenerated(true);notify('Isi kartu siap. Gambar Pixabay sedang dicari; pilih yang paling sesuai.')}}catch(e){if(mounted.current){setError(e.message);request.current=null}}finally{guard.current=false;if(mounted.current)setBusy('')}
 }
